def main():
 out=[]
 for well,(page,rows) in S.items():
  file=P[well]['file'];raw=' '.join((PdfReader(file).pages[page-1].extract_text() or '').split());items=[]
  for en,fa,top,bottom,spec,anchor in rows:
   assert anchor in raw,(well,page,anchor);assert 0<=top<bottom
   items.append({'label_en':en,'label_fa':fa,'from_m':top,'to_m':bottom,'specification':spec,'source_anchor':anchor})
  out.append({'well':well,'file':file,'physical_page':page,'scope':('Planned design only, not as-built.' if well=='207' else ('Programme marks first two as already run; remaining entries are design, not verified as-built.' if well=='40' else ('Explicitly before sidetrack 2; not the later configuration.' if well=='127ST2' else 'Programme-stated historical/pre-operation intervals; status and depth reference require reconciliation. Not an as-built schematic.'))) ,'intervals':items})
 Path('evidence/program_casing_intervals_reviewed.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(len(out),'PDF pages;',sum(len(x['intervals']) for x in out),'intervals')
if __name__=='__main__':main()
